using System;

public struct Quote
{
    public string Id;
    public string Text;
    public string Author;
}

public static class GermanQuotes
{
    public static readonly Quote[] Quotes = new Quote[]
    {
        new Quote { Id = "https://de.wikiquote.org/wiki/Ii_Naosuke", Text = "Einmal Leben. Einmal Treffen.", Author = "Ii Naosuke" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Phil_Ochs", Text = "Ich kann mit Phil einfach nicht mithalten. Und er wird immer besser und besser und besser..", Author = "Phil Ochs" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gerald_H%C3%BCther", Text = "Kinder unter Daueraufsicht, die immer nur an der Hand von Erwachsenen umhergeführt werden, gleichen Haustieren, Stalleseln, die das Leben in der Freiheit nicht mehr kennen.", Author = "Gerald Hüther" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Fundament", Text = "An den großen Entdeckungen kann ich mich nur wenig freuen, weil sie mir das Verstehen des Fundaments vorläufig nicht zu erleichtern scheinen.", Author = "Fundament" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Athlet", Text = "Die Spiele müssen weitergehen; wir müssen in unserem Bemühen fortfahren, sie rein und ehrlich zu halten und zu versuchen, die sportliche Haltung der Athleten in andere Bereiche zu tragen.", Author = "Athlet" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Spiel", Text = "Der ernsteste Stoff muss so behandelt werden, dass wir die Fähigkeit behalten, ihn unmittelbar mit dem leichtesten Spiel zu vertauschen.", Author = "Spiel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Degen", Text = "Den deutschen Mannen gereicht´s zum Ruhm, // Dass sie gehasst das Christentum, // Bis Herrn Carolus leidigem Degen // Die edlen Sachsen unterlegen.", Author = "Degen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gewissensbisse", Text = "Die Begierde nach einer Frau, die man besessen hat, ist etwas Grauenvolles und tausendmal schlimmer als alles andere; fürchterliche Phantasiebilder verfolgen einen wie Gewissensbisse.", Author = "Gewissensbisse" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Georg_Friedrich_H%C3%A4ndel", Text = "Für Händel ein eigenes Gestelle - dies Gestelle muss bei jeder Lücke eine Leiste haben, welche leicht beweglich zu machen, so für größere und kleinere Bücher.", Author = "Georg Friedrich Händel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Todesopfer_an_der_Berliner_Mauer", Text = "Das Leben eines jeden einzelnen unserer tapferen Jungen in Uniform ist uns mehr wert, als das Leben eines Gesetzesbrechers. Soll man von unserer Staatsgrenze wegbleiben – dann kann man sich Blut, Tränen und Geschrei sparen.", Author = "Todesopfer an der Berliner Mauer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ausdruckskraft", Text = "Der Geist ist es, der den Redner macht, und die Ausdruckskraft der Empfindung.", Author = "Ausdruckskraft" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hy%C3%A4ne", Text = "Da werden Weiber zu Hyänen // Und treiben mit Entsetzen Scherz.", Author = "Hyäne" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Joseph_Wirth", Text = "Da steht (nach rechts) der Feind, der sein Gift in die Wunden eines Volkes träufelt. - Da steht der Feind - und darüber ist kein Zweifel: dieser Feind steht rechts!", Author = "Joseph Wirth" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Logik", Text = "Alle Sätze der Logik sagen aber dasselbe. Nämlich Nichts.", Author = "Logik" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Jakob_Johann_von_Uexk%C3%BCll", Text = "Alle Wirklichkeit ist subjektive Erscheinung - dies muss die grosse grundlegende Erkenntnis auch der Biologie bilden. Ganz umsonst wird man die gesamte Welt durchstöbern nach Ursachen, die unabhängig vom Subjekt sind, immer wird man auf Gegenstände stossen, die ihren Aufbau dem Subjekt verdanken.", Author = "Jakob Johann von Uexküll" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Laotse", Text = "Auch der längste Marsch beginnt mit dem ersten Schritt.", Author = "Laotse" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Friedrich_Wolf", Text = "Eine Giftschlange zähmt man nit, man zertritt sie!", Author = "Friedrich Wolf" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Norbert_Elias", Text = "Die ‚Umstände‘, die sich ändern, sind nichts, was gleichsam von ‚außen‘ an den Menschen herankommt; die ‚Umstände‘, die sich ändern, sind die Beziehungen zwischen den Menschen selbst. Der Mensch ist ein außerordentlich modellierbares und variables Wesen [...].", Author = "Norbert Elias" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Italiener", Text = "Das Paradies, das wären ein französischer Koch, ein britischer Polizist, ein deutscher Manager und ein italienischer Liebhaber. Die Hölle, das sind ein britischer Koch, ein deutscher Polizist, ein italienischer Manager und ein französischer Liebhaber.", Author = "Italiener" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Leo_Trotzki", Text = "Jeder Staat wird auf Gewalt gegründet.", Author = "Leo Trotzki" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Abendmahl", Text = "Fehlt es dem protestantischen Kultus im ganzen an Fülle, so untersuche man das einzelne, und man wird finden, der Protestant hat zu wenig Sakramente, ja er hat nur eins, bei dem er sich tätig erweist, das Abendmahl: denn die Taufe sieht er nur an andern vollbringen, und es wird ihm nicht wohl dabei.", Author = "Abendmahl" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Leuchten", Text = "Glauben Sie, meine Herren, es wird kein Haupt über Deutschland demokratischen Öls gesalbt ist!", Author = "Leuchten" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Allen_Ginsberg", Text = "„Ich sah die besten Köpfe meiner Generation zerstört vom Wahnsinn, hungrig hysterisch nackt, // wie sie im Morgengrauen sich durch die Negerstraßen schleppten auf der Suche nach einer wütenden Spritze", Author = "Allen Ginsberg" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Claudia_Kemfert", Text = "Klimaschutz ist kein Luxus in Boomzeiten – sondern unser Weg aus der Krise. Es muß nicht heißen: Erst einmal nicht. Sondern: Jetzt erst recht!", Author = "Claudia Kemfert" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Nachbesserung", Text = "Am besten machst du gleich dein Ding im Anfang recht, // Nachbesserung macht oft Halbgutes völlig schlecht.", Author = "Nachbesserung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ludwig_Tieck", Text = "Die Tragödie ist das Gebiet aller hohen Affekte, der Extreme der Leidenschaften.", Author = "Ludwig Tieck" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kamo_no_Ch%C5%8Dmei", Text = "Am Morgen gestorben, am Abend geboren, das ist das Geschick des Menschen - gleich den Schaumblasen auf dem Wasser. Und dieser Mensch, der geboren wird und stirbt, wer weiß schon, woher er kommt, wohin er geht?", Author = "Kamo no Chōmei" },
        new Quote { Id = "https://de.wikiquote.org/wiki/G%C3%BCnther_Oettinger", Text = "Anders als in einigen Nachrufen zu lesen, gilt es festzuhalten: Hans Filbinger war kein Nationalsozialist. Im Gegenteil: Er war ein Gegner des NS-Regimes.", Author = "Günther Oettinger" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Herkunft", Text = "Die größten Feinde des Leistungsgedanken sind die, die aufgrund ihrer Herkunft, ihres Vermögens oder Ähnlichem Erfolg haben. Und ihnen sollen wir den Leistungsbegriff überlassen? Sicher nicht!", Author = "Herkunft" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Tassilo_K%C3%BCpper", Text = "Elitär drückt eine Geisteshaltung aus, etwas, das man für sich in Anspruch nimmt. Wichtig ist jedoch das Handeln der Menschen.", Author = "Tassilo Küpper" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Schlaflosigkeit", Text = "30 Minuten nach Spielschluss werden schon wieder Karten gespielt und Sprüche geklopft. Die Spieler essen Scampis und ich habe eine schlaflose Nacht.", Author = "Schlaflosigkeit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Siegfried_Lenz", Text = "Ich bekenne, ich brauche Geschichten, um die Welt zu verstehen, - und zwar in gleicher Weise, wie andere womöglich die Formel brauchen, das Dokument.", Author = "Siegfried Lenz" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gottfried_Amann", Text = "Der Mensch sollte ihnen mit Rücksicht begegnen, seinen Sammeltrieb mäßigen und sie keineswegs mutwillig zerstören, auch wenn sie ihm alt, unbekannt, ungenießbar oder giftig erscheinen.", Author = "Gottfried Amann" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Haltung", Text = "Ästhetik allein genügt nicht - nein, eine politische, gesellschaftliche Haltung ist stets vonnöten. Sonst droht Verfall.", Author = "Haltung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Erwartung", Text = "Die bittersten Worte, die Menschen einander sagen, wirken selten so entzweiend wie die unausgesprochenen, die der eine vom andern vergeblich erwartet.", Author = "Erwartung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/J%C3%BCrgen_W._Gansel", Text = "Auf diesen bundesdeutschen Stasi-Staat, der keine Demokratie, sondern deren Karikatur ist, spucke ich.", Author = "Jürgen W. Gansel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Nicolai_Hartmann", Text = "Liebe ist die absolut positive Gesinnung als solche, die Bejahung, Gunst, Hingabe, aufbauende Tendenz - wie denn der Hass Verneinung, Umsturz, Vernichtung ist. Persönliche Liebe ist dieselbe Bejahung in bezug auf die Persönlichkeit.", Author = "Nicolai Hartmann" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Stahl", Text = "Deutschland ist untergegangen in einem Bad von Stahl. Heraldische Drachen und Schlangen beten zum biblischen Baal.", Author = "Stahl" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bauer", Text = "Geschickte Ackerbauer und Handwerker sollen belohnt werden.", Author = "Bauer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bezahlung", Text = "Aber du musst mich auch bezahlen, sagte die Hexe, und es ist nicht wenig, was ich verlange!", Author = "Bezahlung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Braunschweig", Text = "Braunschweiger Bierbrauerburschen brauen brausiges braunschweiger Braunbier.", Author = "Braunschweig" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Claudia_Roth", Text = "Natürlich darf man sich freuen, wenn die deutsche Mannschaft gut spielt und gewinnt. Und ich will auch niemandem verbieten, ein Fähnchen aufzuhängen. Ich finde aber, dass es uns Deutschen gut zu Gesicht steht, wenn wir Zurückhaltung walten lassen.", Author = "Claudia Roth" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Million", Text = "Millionen von Arbeitsstunden gehen jedes Jahr durch unzureichende Lehrbücher verloren.", Author = "Million" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Walter_Gropius", Text = "Ein Ding ist bestimmt durch sein Wesen. Um es so zu gestalten, daß es richtig funktioniert – ein Gefäß, ein Stuhl, ein Haus –, muß sein Wesen zuerst erforscht werden; denn es soll seinem Zweck vollendet dienen, d.h. seine Funktion praktisch erfüllen, haltbar, billig und ‚schön‘ sein.", Author = "Walter Gropius" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Gottesdienst", Text = "Dem Gottesdienst soll nichts vorgezogen werden.", Author = "Gottesdienst" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Johannes_Scherr", Text = "Aller Anfang ist schwer, ja wohl; aber das rechtzeitige Aufhören ist eine noch schwierigere Kunst.", Author = "Johannes Scherr" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hans_Fallada", Text = "Denn so sind die Menschen: eine gemeinsame Furcht führt sie leichter zusammen als eine gemeinsame Liebe.", Author = "Hans Fallada" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Der_Letzte", Text = "Aber ich werde der letzte nicht sein, den es bitter gereute, // Frauenrat befolget zu haben.", Author = "Der Letzte" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Edward_Abbey", Text = "Wachstum um des Wachstums willen ist die Ideologie der Krebszelle.", Author = "Edward Abbey" },
        new Quote { Id = "https://de.wikiquote.org/wiki/M%C3%BCnster", Text = "Entweder regnet es in Münster, oder es läuten die Glocken. Geschieht beides gleichzeitig, ist Sonntag.", Author = "Münster" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Nerv", Text = "Das körperliche Herz sei das Muster des geistigen: verletzbar, empfindlich, rege und warm, aber ein derber, frei fortschlagender Muskel hinter dem Knochengitter, und seine zarten Nerven sind schwer zu finden.", Author = "Nerv" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Joseph_Goebbels", Text = "Auch die gute Laune ist kriegswichtig. Sie zu erhalten, und zwar gerade dann, wenn wir besonders schwere Belastungen zu ertragen haben, ist ein dringendes Erfordernis einer erfolgreichen Kriegführung an der Front und in der Heimat.", Author = "Joseph Goebbels" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Augenblick", Text = "Alles zerfällt im Augenblicke, wenn man nicht ein Dasein erschaffen hat, das über dem Sarge noch fortdauert. Um wen bei seinem Alter Söhne, Enkel und Urenkel stehen, der wird oft tausend Jahre alt.", Author = "Augenblick" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Madrid", Text = "Nach Madrid ist nur der Himmel schöner!", Author = "Madrid" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kategorischer_Imperativ", Text = "Handle so, dass die Maxime deines Willens jederzeit zugleich als Prinzip einer allgemeinen Gesetzgebung gelten könne.", Author = "Kategorischer Imperativ" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Fusion", Text = "Ein geeignetes Mittel zur Humanisierung von Makrostrukturen ist die Mikrozonierung, die anstelle von Fusion und Subordination Opposition und Konfrontation setzt und überschaubare Einheiten schafft, in denen sich der Mensch als Maßeinheit wiedererkennt.", Author = "Fusion" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Verbrechen", Text = "Alle Verbrechen sind auch vor dem Erfolg der Tat, soweit genug Schuld besteht, ausgeführt.", Author = "Verbrechen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Heinz_Marecek", Text = "Es ist das wichtigste Ventil unseres Lebens! So wie wir schwitzen, wenn es uns zu heiß ist, lachen wir, wenn sich unser Emotions-Apparat überhitzt.", Author = "Heinz Marecek" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Mick_Jagger", Text = "Früher habe ich mich mit Drogen und anderen schlimmen Sachen vollgepumpt. Heute gehe ich lieber mit einem schönen Mädchen ins Bett.", Author = "Mick Jagger" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Freundschaft", Text = "Am tiefsten schmerzen Wunden, uns geschlagen // Von Feinden, die der Freundschaft Larve tragen.", Author = "Freundschaft" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Douglas_R._Hofstadter", Text = "Dieser Satz enthält genau trei Feehler.", Author = "Douglas R. Hofstadter" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Brot", Text = "Ach, es ist doch ein saures Stück Brot, das Philosophieprofessorenbrot!", Author = "Brot" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Originalit%C3%A4t", Text = "Alles Gute, das besteht, ist eine Frucht der Originalität.", Author = "Originalität" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Zusammenleben", Text = "Die Musik kann das Zusammenleben erleichtern. Aber das Wichtigste ist Bildung und medizinische Versorgung.", Author = "Zusammenleben" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Josip_Broz_Tito", Text = "Stalin: Hör auf, Leute zu schicken, um mich umzubringen. Wir haben schon fünf von ihnen gefangen, einer davon mit einer Bombe und ein anderer mit einem Gewehr... Wenn Du nicht aufhörst, Mörder zu schicken, werde ich einen nach Moskau schicken, und ich werde keinen zweiten schicken müssen.", Author = "Josip Broz Tito" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ariadne_von_Schirach", Text = "Der Körper ist kostbar, und unsere Lust ist es auch!", Author = "Ariadne von Schirach" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Kylie_Minogue", Text = "Ich kann meine alten Videos nicht mehr anschauen, ohne mich zu schämen. Schwulenikonen haben normalerweise ein tragisches Leben. Ich hatte bloß tragische Frisuren und Outfits.", Author = "Kylie Minogue" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Monika_Piel", Text = "Den Geburtsfehler des Internets – kostenlose Inhalte - zu beseitigen ist aber schwierig und langwierig.", Author = "Monika Piel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/CSU", Text = "Die CSU und ihre Führung muss den Stolz der Bayern verkörpern. Das ist der entscheidende Maßstab.", Author = "CSU" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Truman_Capote", Text = "Ich bin schwul. Ich bin süchtig. Ich bin ein Genie.", Author = "Truman Capote" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ai_Weiwei", Text = "Ich meine, wenn wir aufgeben, dann sind wir Teil des Verbrechens.", Author = "Ai Weiwei" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Pr%C3%A4sident", Text = "Die Wahl des Präsidenten ist damit blockiert und es ist auch in Zukunft fast unmöglich für das Parlament, einen Präsidenten zu wählen. Die Entscheidung des Verfassungsgerichts ist eine Kugel, die gegen die Demokratie gerichtet ist.", Author = "Präsident" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Maharishi_Mahesh_Yogi", Text = "Die eigentliche Natur des Seins ist Seligkeitsbewusstsein. Ohne die Kenntnis seiner Grundlage, des absoluten Seligkeits-Bewusstseins, ist das Leben wie ein Haus ohne Fundament.", Author = "Maharishi Mahesh Yogi" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Wolfgang_Schuster", Text = "Ich träume von einer Stadt, in der Kinder willkommen sind, in der sie faire Chancen haben und in der Familien und deren Kinder auch als Mieter und als Nutzer öffentlicher Plätze gerne gesehen sind. Ich träume von einer Stadt, in der man akzeptiert, dass Kinder Freiräume brauchen.", Author = "Wolfgang Schuster" },
        new Quote { Id = "https://de.wikiquote.org/wiki/W%C3%BCrfel", Text = "Der Würfel ist geworfen worden.", Author = "Würfel" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Empathie", Text = "Was ich in meinem Leben will, ist Einfühlsamkeit, ein Fluss zwischen mir und anderen, der auf gegenseitigem Geben von Herzen beruht.", Author = "Empathie" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Tausch", Text = "Beneide niemanden, denn du weißt nicht, ob der Beneidete im stillen nicht etwas verbirgt, was du bei einem Tausche nicht übernehmen möchtest.", Author = "Tausch" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Paul_Sethe", Text = "Ich weiß, dass es im deutschen Pressewesen Oasen gibt, in denen noch die Luft der Freiheit weht. Ich bin glücklich, in einer solchen Oase zu leben. Aber wie viele von meinen Kollegen können das von sich sagen?", Author = "Paul Sethe" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Rot_%28Farbe%29", Text = "Wie willst du weiße Lilien zu roten Rosen machen? // Küss eine weiße Galathee: Sie wird errötend lachen.", Author = "Rot (Farbe)" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Eifer", Text = "Alles gelingt, was man mit rechtem Eifer angreift.", Author = "Eifer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/George_Sand", Text = "Nach der Liebe ist die Eitelkeit die schönste Leidenschaft des Menschen […] Sie zwingt uns, gut zu sein, aus dem Drang heraus, so zu scheinen.", Author = "George Sand" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Klage", Text = "Der Säugling, des Gesanges müde, // Ruht aus von seinem Klageliede.", Author = "Klage" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bundeswehr", Text = "Mögliches Einsatzgebiet für die Bundeswehr ist die ganze Welt.", Author = "Bundeswehr" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Donner", Text = "Gott […] deine Stimme ist leise geworden – zu leise für den Donner unserer Zeit. Wir können dich nicht mehr hören.", Author = "Donner" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Pr%C3%A4nataldiagnostik", Text = "Kaum ein Kind kommt heute auf die Welt, ohne dass es eine mehrstufige Qualitätskontrolle durchlaufen hat.", Author = "Pränataldiagnostik" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Johann_Nepomuk_Vogl", Text = "Auf der Alm, da gibt's kan Sünd'.", Author = "Johann Nepomuk Vogl" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ma%C3%9F", Text = "Aufgabe der Erziehung wäre es, den metaphysischen Hunger des Menschen durch Mitteilung von Tatsachen in weisem Maß zu stillen, statt ihn durch Märchen, was ja die Dogmen sind, zu betrügen.", Author = "Maß" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Unerfahrenheit", Text = "Einem Unerfahrenen Lebensregeln geben, heißt einem Ungeübten Unterricht im Fechten durch Zuschauen zu geben.", Author = "Unerfahrenheit" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Engl%C3%A4nder", Text = "Der Engländer wiegt sich gern in dem Glauben, er könne über sich selbst lachen. Das tut er jedoch nur, um anderen den Spaß daran zu verderben, über ihn zu lachen.", Author = "Engländer" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Bruce_Springsteen", Text = "Über Musik sprechen geht nicht, das wäre das gleiche als würde man über Sex sprechen. Man kann darüber nicht sprechen, man muss es erleben.", Author = "Bruce Springsteen" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Ludwig_Anzengruber", Text = "Bescheidenheit ist der Anfang aller Vernunft.", Author = "Ludwig Anzengruber" },
        new Quote { Id = "https://de.wikiquote.org/wiki/James_Fenimore_Cooper", Text = "Mancher ist schon mit dem Ausdrucke des Heldenmutes auf seinen Lippen heimgegangen, während sein Herz schwer und trostlos war.", Author = "James Fenimore Cooper" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Augustinus_Patricius", Text = "Heiliger Vater, so vergeht der Ruhm der Welt.", Author = "Augustinus Patricius" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Jimmy_Carter", Text = "Strafen gegen den Besitz einer Droge sollten für ein Individuum nicht schädlicher sein als der Konsum der Droge selbst; und wo es so ist, sollte es geändert werden. Nirgendwo ist es deutlicher als in den Gesetzen gegen den persönlichen Besitz von Marihuana für privaten Konsum.", Author = "Jimmy Carter" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Hans_Bibelriether", Text = "Natur Natur sein lassen.", Author = "Hans Bibelriether" },
