        new Quote { Id = "https://de.wikiquote.org/wiki/Besinnung", Text = "Allen Segens Anfang heißt Besinnung, was der Götter ist entweihe keiner! Überhebung büßt mit großem Falle, dem Alter zur Besinnung.", Author = "Besinnung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/Verwendung", Text = "Niemand gibt das Geld anderer Leute so sorgsam aus wie das eigene. Niemand geht mit den Ressourcen anderer so sorgsam um wie mit den eigenen. Wer also Effektivität und Effizienz möchte, wer sorgsame Verwendung gewährleisten will, der muss dies mittels Privateigentum tun.", Author = "Verwendung" },
        new Quote { Id = "https://de.wikiquote.org/wiki/David_Ricardo", Text = "Ricardo bietet uns die höchste geistige Leistung, unerreichbar für schwächere Geister, eine hypothetische Welt außerhalb der Wirklichkeit anzunehmen als ob sie die Welt der Wirklichkeit wäre, und dann beständig in ihr zu leben.", Author = "David Ricardo" },
